import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

//Écran de chargement : le compteur monte, puis le rideau remonte quand la page est chargée
export default class Loader {
  constructor(element) {
    this.element = element;
    this.init();
  }

  init() {
    this.count = this.element.querySelector('.js-loader-count');
    this.fill = this.element.querySelector('.loader__fill');
    this.progress = { value: 0 };

    //Bloque le scroll (le ScrollSmoother est créé juste après le Loader)
    gsap.delayedCall(0, () => ScrollSmoother.get()?.paused(true));

    //Le compteur monte jusqu'à 90 % pendant au moins 1,6 s
    const intro = gsap.to(this.progress, { value: 90, duration: 1.6, ease: 'power1.out', onUpdate: () => this.update() });

    //Quand la page est chargée ET que le compteur est à 90 % : on finit
    const loaded = new Promise((resolve) => (document.readyState === 'complete' ? resolve() : window.addEventListener('load', resolve)));
    Promise.all([loaded, intro]).then(() => this.finish());
  }

  update() {
    this.count.textContent = String(Math.round(this.progress.value)).padStart(3, '0');
    this.fill.style.transform = `scaleX(${this.progress.value / 100})`;
  }

  finish() {
    gsap
      .timeline({ onComplete: () => this.destroy() })
      .to(this.progress, { value: 100, duration: 0.4, onUpdate: () => this.update() })
      .to(this.element.querySelector('.loader__inner'), { opacity: 0, y: 20, duration: 0.4 })
      .to(this.element, { clipPath: 'inset(0% 0% 100% 0%)', duration: 1, ease: 'expo.inOut' });
  }

  destroy() {
    ScrollSmoother.get()?.paused(false);
    ScrollTrigger.refresh();
    window.dispatchEvent(new CustomEvent('loader:complete')); //Prévient les autres composantes (ex. Modal)
    this.element.remove();
  }
}
