import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class Lines {
  constructor(element) {
    //register des plugins mis dans le gsap
    gsap.registerPlugin(ScrollSmoother, ScrollTrigger);
    this.element = element;
    this.options = {
      offset: -250,
    };

    this.line = this.element.querySelector('.path-ligne');
    this.path = this.element.querySelector('path');
    this.pathLength = this.path.getTotalLength();
    this.panels = this.element.querySelectorAll('.js-panel');

    this.init();
  }

  init() {
    this.setOptions();

    if (this.line && this.panels.length) {
      this.initHoriz();
      return;
    }

    gsap.set(this.path, {
      strokeDasharray: this.pathLength,
      strokeDashoffset: this.pathLength,
    });

    gsap.to(this.path, {
      strokeDashoffset: this.options.offset,
      ease: 'none',
      scrollTrigger: {
        trigger: this.element,
        start: 'top center',
        end: 'bottom center',
        scrub: 0.5,
      },
    });
  }

  setOptions() {
    if ('offset' in this.element.dataset) {
      this.options.offset = this.element.dataset.offset;
    }
  }

  /* ==========================================================================
      / Ligne horizontale (compétences)
     ========================================================================== */

  //La ligne ne suit pas le scroll : elle suit directement l'apparition des cartes.
  //Peu importe le resize, le mobile ou les réglages de Scroll.js, elle reste synchronisée.
  initHoriz() {
    this.svg = this.line.closest('svg');
    this.reveal = -1;

    //Lit le stagger et la durée directement dans l'animation des cartes de Scroll.js
    const tween = gsap.getTweensOf(this.panels).find((t) => t.scrollTrigger);
    this.stagger = tween && typeof tween.vars.stagger === 'number' ? tween.vars.stagger : 0.2;
    this.duration = tween && tween.vars.duration ? tween.vars.duration : 0.5; //0.5 = durée par défaut de GSAP

    // Chaque carte dessine le segment sous sa colonne : quand elle a fini d'apparaître,
    // la ligne atteint le point de la colonne suivante (fin de ce point, en % du viewBox de 1205).
    // La dernière carte termine la ligne.
    const nextDotEnds = [429, 837];
    this.stops = Array.from(this.panels, (panel, i) =>
      i === this.panels.length - 1 ? 100 : (nextDotEnds[i] / 1205) * 100,
    );

    //Moment où chaque carte a fini d'apparaître (dans le temps de l'animation)
    this.arrivals = Array.from(this.panels, (panel, i) => i * this.stagger + this.duration);

    this.updateLine = this.updateLine.bind(this);
    gsap.ticker.add(this.updateLine);
  }

  updateLine() {
    //1. Retrouve où en est l'animation des cartes à partir de leur opacité.
    //   Les cartes se chevauchent (stagger), donc on prend la plus avancée.
    let time = 0;
    this.panels.forEach((panel, i) => {
      const opacity = gsap.getProperty(panel, 'opacity');
      if (opacity > 0) {
        time = Math.max(time, i * this.stagger + this.duration * opacity);
      }
    });

    //2. Convertit ce temps en longueur de ligne : elle atteint chaque point
    //   le segment sous chaque colonne se dessine pendant que sa carte apparaît, sans saut
    let reveal = 100;
    let previousTime = 0;
    let previousStop = 0;
    for (let i = 0; i < this.arrivals.length; i++) {
      if (time <= this.arrivals[i]) {
        const progress = (time - previousTime) / (this.arrivals[i] - previousTime);
        reveal = previousStop + (this.stops[i] - previousStop) * progress;
        break;
      }
      previousTime = this.arrivals[i];
      previousStop = this.stops[i];
    }

    //Ne touche au style que si la ligne a changé
    if (Math.abs(reveal - this.reveal) < 0.05) return;
    this.reveal = reveal;
    this.svg.style.clipPath = `inset(0% ${100 - reveal}% 0% 0%)`;
  }
}
