import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class Scroll {
  constructor(element) {
    //register des plugins mis dans le gsap
    gsap.registerPlugin(ScrollSmoother, ScrollTrigger);
    this.options = {
      hasPinItems: true,
    };

    this.panels = gsap.utils.toArray('.animation_section');
    this.panels.pop();

    this.element = element;
    this.init();
  }

  /* ==========================================================================
      / Init
     ========================================================================== */

  init() {
    //Permet de rendre le scroll plus smooth et le temps avant que le scroll rattrape
    this.scroller = ScrollSmoother.create({
      wrapper: '#smooth-wrapper',
      content: '#smooth-content',
      smooth: 1.5,
      effects: true,
      smoothTouch: 0.1,
      onUpdate: this.onUpdateScroll.bind(this),
      ease: 'expo.out',
    });
    this.setOptions();
    this.animationPanels();
    this.initAnchors();
  }

  /* ==========================================================================
      / Update pour le scroll
     ========================================================================== */

  onUpdateScroll(self) {
    if (this.options.hasSkew) this.updateSkew(self);
  }

  /* ==========================================================================
      / Set Options
     ========================================================================== */

  setOptions() {
    if ('pinItems' in this.element.dataset) {
      this.options.hasPinItems = true;
      this.initPins();
    }
  }

  /* ==========================================================================
      / Init des Pinned Items pour le Scroll Horizontal
     ========================================================================== */

  initPins() {
    const pinnedItems = this.element.querySelectorAll('.js-pinned');
    for (let i = 0; i < pinnedItems.length; i++) {
      const pinnedItem = pinnedItems[i];

      ScrollTrigger.create({
        pin: pinnedItem,
        trigger: pinnedItem.parentElement,
        start: 'center center',
        end: '80% center',
      });
    }

    if (this.element.querySelector('.js-horiz')) {
      this.initHoriz();
    }
  }

  //Permet de faire défiller des panneaux à l'horizontal et controlable avec le scrub qui li le scroll avec la progression du scroll et non directement au bout de la section
  initHoriz() {
    const sectionHoriz = this.element.querySelector('.js-horiz');
    const panels = sectionHoriz.querySelectorAll('.js-panel');
    const nbPanels = panels.length - 1;
    const buffer = 200;
    //Vitesse du défilement horizontal : 1.3 = 30% plus rapide qu'au départ
    const speed = 1.3;

    const mm = gsap.matchMedia();

    //Ordi : les cartes apparaissent une après l'autre pendant que la section est épinglée
    mm.add('(min-width: 901px)', () => {
      gsap.to(panels, {
        opacity: 1,
        x: 0,
        stagger: 0.2,
        ease: 'none',
        scrollTrigger: {
          pin: true,
          trigger: sectionHoriz,
          start: 'top 20%',
          scrub: 1 / speed,
          snap: 1 / nbPanels,
          pinSpacing: 0.5,
          //Moins de distance de scroll = les cartes défilent plus vite
          end: () => '+=' + sectionHoriz.offsetWidth / speed,
        },
      });
    });

    //Mobile : pas d'épinglage, chaque carte apparaît simplement quand on arrive dessus
    mm.add('(max-width: 900px)', () => {
      panels.forEach((panel) => {
        gsap.fromTo(
          panel,
          { opacity: 0, y: 40 },
          { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out', scrollTrigger: { trigger: panel, start: 'top 85%' } },
        );
      });
    });
  }

  /* ==========================================================================
      / Section qui anime les deux panneaux pour qu'il viennent overlap dans hub
     ========================================================================== */

  animationPanels() {
    this.panels.forEach((panel, i) => {
      //Prend le container du contenu
      var innerpanel = panel.querySelector('.wrapper');

      // Récupère la hauteur du contenu
      var panelHeight = innerpanel.offsetHeight;

      // Prend la hauteur de la fenetre
      var windowHeight = window.innerHeight;
      var difference = panelHeight - windowHeight;

      // ratio (between 0 and 1) representing the portion of the overall animation that's for the fake-scrolling. We know that the scale & fade should happen over the course of 1 windowHeight, so we can figure out the ratio based on how far we must fake-scroll
      var fakeScrollRatio =
        difference > 0 ? difference / (difference + windowHeight) : 0;

      // if we need to fake scroll (because the panel is taller than the window), add the appropriate amount of margin to the bottom so that the next element comes in at the proper time.
      if (fakeScrollRatio) {
        panel.style.marginBottom = panelHeight * fakeScrollRatio + 'px';
      }

      var tl = gsap.timeline({
        scrollTrigger: {
          trigger: panel,
          start: 'bottom bottom',
          end: () =>
            fakeScrollRatio ? `+=${innerpanel.offsetHeight}` : 'bottom top',
          pinSpacing: false,
          pin: true,
          scrub: true,
        },
      });

      // fake scroll. We use 1 because that's what the rest of the timeline consists of (0.9 scale + 0.1 fade)
      if (fakeScrollRatio) {
        tl.to(innerpanel, {
          yPercent: -100,
          y: window.innerHeight,
          duration: 1 / (1 - fakeScrollRatio) - 1,
          ease: 'none',
        });
      }
      tl.to(panel, {
        opacity: 0,
        duration: 0.5,
      });
    });
  }

  /* ==========================================================================
      / Section pour le bon fonctionnement des anchors
     ========================================================================== */

  initAnchors() {
    console.log('initAnchors');
    document.querySelectorAll('a[href^="index.html#"]').forEach((anchor) => {
      anchor.addEventListener('click', (i) => {
        const href = anchor.getAttribute('href').split('#').pop();
        if (!href || href.length < 2) return;

        const target = document.querySelector('#' + href);
        if (!target) return;
        console.log('test');
        i.preventDefault();
        this.scroller.scrollTo(target, true, 'top top'); // true = animated
      });
    });

    window.addEventListener('load', () => {
      if (!location.hash) return;
      const target = document.querySelector(location.hash);
      if (target) this.scroller.scrollTo(target, false, 'top top'); // instant
    });
  }
}
