import { gsap } from 'gsap';
import * as THREE from 'three';

export default class CircularGallery {
  constructor(element) {
    this.element = element;
    this.options = {
      bend: 3, //Courbure de l'arc (0 = plat)
      borderRadius: 0.05, //Coins arrondis des images
      mobileWidth: 1000, //En dessous : textes toujours visibles, pas de survol
    };

    this.cards = [];
    this.scroll = { current: 0, target: 0, start: 0 };
    this.isDown = false;
    this.hovered = null;
    this.raycaster = new THREE.Raycaster();
    this.pointer = new THREE.Vector2();

    this.init();
  }

  /* ==========================================================================
      / Init
     ========================================================================== */

  init() {
    this.setOptions();
    this.createScene();
    this.initEvents();

    //Attend la police du site avant de dessiner les textes
    document.fonts.ready.then(() => {
      this.createCards();
      this.onResize();

      this.update = this.update.bind(this);
      gsap.ticker.add(this.update);
    });
  }

  setOptions() {
    for (const key in this.options) {
      if (key in this.element.dataset) {
        this.options[key] = parseFloat(this.element.dataset[key]);
      }
    }
  }

  /* ==========================================================================
      / Scène Three.js
     ========================================================================== */

  createScene() {
    this.renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.canvas = this.renderer.domElement;
    this.canvas.classList.add('circular-gallery__canvas');
    this.element.appendChild(this.canvas);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
    this.camera.position.z = 20;
  }

  /* ==========================================================================
      / Cartes (image + texte), créées à partir des <article> du HTML
     ========================================================================== */

  createCards() {
    const articles = Array.from(this.element.querySelectorAll('article'));
    const textStyle = getComputedStyle(articles[0].querySelector('p'));
    this.geometry = new THREE.PlaneGeometry(1, 1);

    //Liste doublée pour que la boucle infinie n'ait jamais de trou
    const list = articles.concat(articles);

    for (let i = 0; i < list.length; i++) {
      const img = list[i].querySelector('img');
      const text = list[i].querySelector('p').textContent.trim();

      const card = { index: i, group: new THREE.Group() };
      card.image = new THREE.Mesh(
        this.geometry,
        this.createImageMaterial(img.currentSrc || img.src),
      );
      card.text = new THREE.Mesh(
        this.geometry,
        this.createTextMaterial(text, textStyle),
      );
      card.image.userData.card = card; //Pour retrouver la carte au survol

      card.group.add(card.image, card.text);
      this.scene.add(card.group);
      this.cards.push(card);
    }
  }

  //Image en "object-fit: cover" avec coins arrondis
  createImageMaterial(src) {
    const material = new THREE.ShaderMaterial({
      transparent: true,
      visible: false, //Cachée tant que l'image n'est pas chargée
      uniforms: {
        tMap: { value: null },
        uImage: { value: new THREE.Vector2(1, 1) },
        uPlane: { value: new THREE.Vector2(1, 1) },
        uRadius: { value: this.options.borderRadius },
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform sampler2D tMap;
        uniform vec2 uImage;
        uniform vec2 uPlane;
        uniform float uRadius;
        varying vec2 vUv;
        void main() {
          float planeRatio = uPlane.x / uPlane.y;
          float imageRatio = uImage.x / uImage.y;
          vec2 scale = planeRatio > imageRatio ? vec2(1.0, imageRatio / planeRatio) : vec2(planeRatio / imageRatio, 1.0);
          vec4 color = texture2D(tMap, (vUv - 0.5) * scale + 0.5);

          vec2 corner = abs(vUv - 0.5) - (0.5 - uRadius);
          float dist = length(max(corner, 0.0)) - uRadius;
          gl_FragColor = vec4(color.rgb, 1.0 - smoothstep(-0.002, 0.002, dist));
        }
      `,
    });

    new THREE.TextureLoader().load(src, (texture) => {
      material.uniforms.tMap.value = texture;
      material.uniforms.uImage.value.set(
        texture.image.width,
        texture.image.height,
      );
      material.visible = true;
    });

    return material;
  }

  //Texte dessiné dans un canvas, avec la police et la couleur du site
  createTextMaterial(text, style) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const font = `500 28px ${style.fontFamily}`; //28px = 14px x2 pour rester net

    ctx.font = font;
    canvas.width = Math.ceil(ctx.measureText(text).width) + 20;
    canvas.height = 48;
    ctx.font = font;
    ctx.fillStyle = style.color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;

    const material = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      opacity: 0,
    });
    material.userData.aspect = canvas.width / canvas.height;
    return material;
  }

  /* ==========================================================================
      / Events
     ========================================================================== */

  initEvents() {
    this.onPointerDown = this.onPointerDown.bind(this);
    this.onPointerMove = this.onPointerMove.bind(this);
    this.onPointerUp = this.onPointerUp.bind(this);
    this.onPointerLeave = this.onPointerLeave.bind(this);

    this.element.addEventListener('pointerdown', this.onPointerDown);
    this.element.addEventListener('pointermove', this.onPointerMove);
    this.element.addEventListener('pointerup', this.onPointerUp);
    this.element.addEventListener('pointercancel', this.onPointerUp);
    this.element.addEventListener('pointerleave', this.onPointerLeave);

    this.resizeObserver = new ResizeObserver(this.onResize.bind(this));
    this.resizeObserver.observe(this.element);
  }

  onPointerDown(e) {
    this.isDown = true;
    this.startX = e.clientX;
    this.scroll.start = this.scroll.target;
    this.element.setPointerCapture(e.pointerId);
  }

  onPointerMove(e) {
    if (this.isDown) {
      //Glisser : 1px de souris = 0.05 unité 3D
      this.scroll.target = this.scroll.start + (this.startX - e.clientX) * 0.05;
    } else {
      this.checkHover(e);
    }
  }

  onPointerUp() {
    if (!this.isDown || !this.cardWidth) return;
    this.isDown = false;
    //Aligne la carte la plus proche au centre
    this.scroll.target =
      Math.round(this.scroll.target / this.cardWidth) * this.cardWidth;
  }

  onPointerLeave() {
    if (!this.isDown) this.setHovered(null);
  }

  /* ==========================================================================
      / Survol (ordinateur seulement)
     ========================================================================== */

  //Lance un rayon depuis la souris pour trouver l'image en dessous
  checkHover(e) {
    if (this.isMobile || !this.cards.length) return;

    const rect = this.element.getBoundingClientRect();
    this.pointer.set(
      ((e.clientX - rect.left) / rect.width) * 2 - 1,
      -((e.clientY - rect.top) / rect.height) * 2 + 1,
    );
    this.raycaster.setFromCamera(this.pointer, this.camera);

    const hit = this.raycaster.intersectObjects(
      this.cards.map((card) => card.image),
    )[0];
    this.setHovered(hit ? hit.object.userData.card : null);
  }

  setHovered(card) {
    if (card === this.hovered) return;
    if (this.hovered) this.showText(this.hovered, false);
    if (card) this.showText(card, true);
    this.hovered = card;
  }

  //Fait apparaître (ou disparaître) le texte avec un léger zoom de la carte
  showText(card, isVisible) {
    gsap.to(card.text.material, {
      opacity: isVisible ? 1 : 0,
      duration: 0.4,
      overwrite: true,
    });
    gsap.to(card.group.scale, {
      x: isVisible ? 1.04 : 1,
      y: isVisible ? 1.04 : 1,
      duration: 0.5,
      overwrite: true,
    });
  }

  /* ==========================================================================
      / Resize
     ========================================================================== */

  onResize() {
    const width = this.element.clientWidth;
    const height = this.element.clientHeight;

    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    //Taille visible de la scène en unités 3D
    this.viewport = {
      height:
        2 * Math.tan(THREE.MathUtils.degToRad(22.5)) * this.camera.position.z,
    };
    this.viewport.width = this.viewport.height * this.camera.aspect;

    //Mobile : textes toujours visibles et plus petits, pas de survol
    this.isMobile = window.innerWidth <= this.options.mobileWidth;
    if (this.isMobile) this.setHovered(null);

    const cardHeight = this.viewport.height * 0.55;
    const cardWidth = cardHeight * 0.78;
    const textHeight = cardHeight * (this.isMobile ? 0.08 : 0.12);
    //Espace entre les cartes : plus grand sur mobile, où l'écran est étroit
    const gap = this.isMobile ? cardWidth * 0.5 : 1.5;
    this.cardWidth = cardWidth + gap;

    for (const card of this.cards) {
      card.image.scale.set(cardWidth, cardHeight, 1);
      card.image.material.uniforms.uPlane.value.set(cardWidth, cardHeight);

      card.text.scale.set(
        textHeight * card.text.material.userData.aspect,
        textHeight,
        1,
      );
      card.text.position.y = -cardHeight / 2 - textHeight;
      card.text.material.opacity = this.isMobile ? 1 : 0;
    }
  }

  /* ==========================================================================
      / Boucle d'animation
     ========================================================================== */

  update() {
    this.scroll.current += (this.scroll.target - this.scroll.current) * 0.08;

    const total = this.cardWidth * this.cards.length;
    const half = this.viewport.width / 2;
    const B = Math.abs(this.options.bend) * (this.isMobile ? 0.5 : 1);
    const dir = Math.sign(this.options.bend); //1 = arc vers le bas, -1 = vers le haut
    const R = (half * half + B * B) / (2 * B); //Rayon de l'arc

    for (const card of this.cards) {
      //Boucle infinie : la position fait le tour quand elle sort d'un côté
      const x = gsap.utils.wrap(
        -total / 2,
        total / 2,
        card.index * this.cardWidth - this.scroll.current,
      );
      card.group.position.x = x;

      //Arc : plus la carte est loin du centre, plus elle descend et tourne
      if (B) {
        const edge = Math.min(Math.abs(x), half);
        card.group.position.y = -dir * (R - Math.sqrt(R * R - edge * edge));
        card.group.rotation.z = -dir * Math.sign(x) * Math.asin(edge / R);
      }
    }

    this.renderer.render(this.scene, this.camera);
  }

  /* ==========================================================================
      / Destroy
     ========================================================================== */

  destroy() {
    gsap.ticker.remove(this.update);
    this.resizeObserver.disconnect();
    this.renderer.dispose();
    this.canvas.remove();
  }
}
