import { gsap } from 'gsap';

export default class Raindrop {
  constructor(element) {
    this.element = element;
    this.dropletQuantity = 60;
    this.droplets = [];

    //Options de l'interaction souris (modifiables avec des data-attributes)
    this.options = {
      mouseInteraction: true,
      mouseStrength: 1.5, //Intensité du flare sur les gouttes
      mouseRadius: 200, //Rayon de la lumière en px
      mouseDampening: 0.15, //Retard de la lumière sur le curseur (secondes)
      trail: true, //Active la traînée lumineuse
      trailDuration: 0.5, //Durée du fade de la traînée (secondes)
      trailSpacing: 40, //Distance en px entre deux copies de la boule dans la traînée
      trailOpacity: 0.3, //Intensité de la traînée par rapport à la boule
    };

    this.mouseInside = false;
    this.flareActive = false;
    this.trailPoints = [];

    this.init();
  }

  init() {
    this.setOptions();

    const fallDistance = 1100;

    for (let i = 0; i < this.dropletQuantity; i++) {
      //Vitesse de chute
      const SpeedVariation = Math.random();
      const speed = 45 + SpeedVariation * 50;
      //Distance / par vitesse pour avoir la vitesse de descente
      const duration = fallDistance / speed;

      //Créer l'élément div.droplet et lui assigne une position random
      const pos = Math.random() * 100;
      const droplet = document.createElement('div');
      droplet.className = 'droplet';
      droplet.style.left = `${pos}%`;

      //Créer des width et height random pour chaque droplets
      const width = 3 + Math.random() * 2;
      const height = 15 + Math.random() * 30;
      droplet.style.width = `${width}px`;
      droplet.style.height = `${height}px`;
      droplet.style.opacity = 1 + Math.random() * 0.1;

      //Assigne les droplet à la page HTML
      this.element.appendChild(droplet);

      //Garde les infos de la goutte pour calculer sa distance avec la souris
      this.droplets.push({
        el: droplet,
        pos: pos,
        width: width,
        height: height,
        top: droplet.offsetTop,
      });

      //Gére les paramètres des droplets individuels
      gsap.to(droplet, {
        y: fallDistance,
        duration: duration,
        delay: -Math.random() * duration,
        repeat: -1,
        ease: 'none',
      });
    }
    //Appelle la fonction qui génère des points
    this.addStaticDots();

    //Appelle la fonction de l'interaction avec la souris
    if (this.options.mouseInteraction) {
      this.initMouse();
    }
  }

  //Lit les data-attributes du HTML (ex: data-mouse-radius="250")
  setOptions() {
    for (const key in this.options) {
      if (!(key in this.element.dataset)) continue;
      const value = this.element.dataset[key];

      if (typeof this.options[key] === 'boolean') {
        this.options[key] = value !== 'false';
      } else {
        this.options[key] = parseFloat(value);
      }
    }
  }

  //Fonction qui crée des points statics blanc dans la page
  addStaticDots() {
    for (let i = 0; i < this.dropletQuantity; i++) {
      const dot = document.createElement('div');
      dot.className = 'dot';

      //Ajoute les sizes et leurs positions de façon random
      const size = 1 + Math.random() * 2; // 1px à 3px
      dot.style.width = `${size}px`;
      dot.style.height = `${size}px`;
      dot.style.left = `${Math.random() * 100}%`;
      dot.style.top = `${Math.random() * 100}%`;
      dot.style.opacity = 0.2 + Math.random() * 0.5;

      //L'ajoute à la page HTML
      this.element.appendChild(dot);
    }
  }

  /* ==========================================================================
      / Interaction souris
     ========================================================================== */

  initMouse() {
    //Crée la lumière qui suit le curseur
    this.halo = document.createElement('div');
    this.halo.className = 'raindrop__halo';
    this.halo.style.setProperty(
      '--halo-size',
      `${this.options.mouseRadius * 2}px`,
    );
    this.element.appendChild(this.halo);

    //Centre la lumière sur le curseur et la cache au départ
    gsap.set(this.halo, { xPercent: -50, yPercent: -50, opacity: 0 });

    //quickTo = suivi doux du curseur (même rôle que le mouseDampening de Lightfall)
    this.haloX = gsap.quickTo(this.halo, 'x', {
      duration: this.options.mouseDampening,
      ease: 'power3.out',
    });
    this.haloY = gsap.quickTo(this.halo, 'y', {
      duration: this.options.mouseDampening,
      ease: 'power3.out',
    });

    if (this.options.trail) {
      this.initTrail();
    }

    //Écoute sur window pour capter la souris même par-dessus le texte
    this.onPointerMove = this.onPointerMove.bind(this);
    window.addEventListener('pointermove', this.onPointerMove, {
      passive: true,
    });

    //Une seule boucle pour tout (flare + traînée) = moins de travail par frame
    this.update = this.update.bind(this);
    gsap.ticker.add(this.update);
  }

  onPointerMove(e) {
    //Position de la souris par rapport à la section
    const rect = this.element.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const inside = x >= 0 && x <= rect.width && y >= 0 && y <= rect.height;

    //Affiche ou cache la lumière quand la souris entre ou sort
    if (inside !== this.mouseInside) {
      this.mouseInside = inside;
      gsap.to(this.halo, { opacity: inside ? 1 : 0, duration: 0.4 });
    }

    this.haloX(x);
    this.haloY(y);
  }

  update() {
    this.updateFlare();

    if (this.options.trail) {
      //La traînée suit la boule (position lissée), pas directement le curseur
      if (this.mouseInside) {
        this.addTrailPoint(
          gsap.getProperty(this.halo, 'x'),
          gsap.getProperty(this.halo, 'y'),
        );
      }
      this.drawTrail();
    }
  }

  updateFlare() {
    //Rien à calculer si la souris est dehors et que les gouttes sont déjà éteintes
    if (!this.mouseInside && !this.flareActive) return;

    //Position actuelle de la lumière (lissée), pas celle du curseur
    const mx = gsap.getProperty(this.halo, 'x');
    const my = gsap.getProperty(this.halo, 'y');
    const radius2 = this.options.mouseRadius * this.options.mouseRadius;
    const elementWidth = this.element.clientWidth;

    let anyActive = false;

    for (const drop of this.droplets) {
      //Centre de la goutte (position de départ + chute animée par GSAP)
      const dx = (drop.pos / 100) * elementWidth + drop.width / 2 - mx;
      const dy =
        drop.top + gsap.getProperty(drop.el, 'y') + drop.height / 2 - my;

      //Falloff gaussien : 1 au centre de la lumière, 0 en s'éloignant
      const glow = this.mouseInside
        ? Math.exp(-(dx * dx + dy * dy) / radius2) * this.options.mouseStrength
        : 0;

      drop.el.style.setProperty('--flare', glow.toFixed(3));
      if (glow > 0.001) anyActive = true;
    }

    this.flareActive = anyActive;
  }

  /* ==========================================================================
      / Traînée lumineuse (canvas 2D)
     ========================================================================== */

  initTrail() {
    //Un seul canvas pour toute la traînée : beaucoup plus léger que des centaines de div
    this.canvas = document.createElement('canvas');
    this.canvas.className = 'raindrop__trail';
    this.element.appendChild(this.canvas);
    this.ctx = this.canvas.getContext('2d');

    this.resizeTrail = this.resizeTrail.bind(this);
    this.resizeObserver = new ResizeObserver(this.resizeTrail);
    this.resizeObserver.observe(this.element);
    this.resizeTrail();
  }

  resizeTrail() {
    //Limite la densité de pixels à 2 pour garder de bonnes performances
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const width = this.element.clientWidth;
    const height = this.element.clientHeight;

    this.canvas.width = width * dpr;
    this.canvas.height = height * dpr;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';
    this.isTrailClear = false;
  }

  addTrailPoint(x, y) {
    const last = this.trailPoints[this.trailPoints.length - 1];

    //Ignore les mouvements de moins de 3px : moins de points à dessiner
    if (last && !last.break) {
      const dx = x - last.x;
      const dy = y - last.y;
      if (dx * dx + dy * dy < 9) return;
    }

    this.trailPoints.push({ x, y, time: performance.now() });
  }

  drawTrail() {
    const now = performance.now();
    const life = this.options.trailDuration * 1000;

    //Retire les points trop vieux (ils sont toujours au début du tableau)
    while (this.trailPoints.length && now - this.trailPoints[0].time > life) {
      this.trailPoints.shift();
    }

    //Plus rien à dessiner : on vide une seule fois puis on ne fait plus rien
    if (this.trailPoints.length < 2) {
      if (!this.isTrailClear) {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        this.isTrailClear = true;
      }
      return;
    }

    const ctx = this.ctx;
    const points = this.trailPoints;
    const maxWidth = this.options.trailWidth;

    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    //'lighter' additionne la lumière : les endroits qui se croisent brillent plus fort
    ctx.globalCompositeOperation = 'lighter';
    this.isTrailClear = false;

    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const point = points[i];
      if (prev.break) continue;

      //0 = point qui vient d'être créé, 1 = point qui va disparaître
      const age = (now - point.time) / life;
      const fade = 1 - age;
      const alpha = fade * fade; //Fade plus doux à la fin

      //Courbe lissée entre les milieux des segments (pas d'angles)
      const startX =
        (prev.x +
          (points[i - 2] && !points[i - 2].break ? points[i - 2].x : prev.x)) /
        2;
      const startY =
        (prev.y +
          (points[i - 2] && !points[i - 2].break ? points[i - 2].y : prev.y)) /
        2;
      const endX = (prev.x + point.x) / 2;
      const endY = (prev.y + point.y) / 2;

      ctx.beginPath();
      ctx.moveTo(startX, startY);
      ctx.quadraticCurveTo(prev.x, prev.y, endX, endY);

      //Lueur large et douce (remplace shadowBlur, qui est très lourd)
      ctx.strokeStyle = `rgba(230, 178, 75, ${alpha * 0.15})`;
      ctx.lineWidth = maxWidth * 4 * fade;
      ctx.stroke();

      //Cœur fin et lumineux
      ctx.strokeStyle = `rgba(255, 230, 170, ${alpha * 0.9})`;
      ctx.lineWidth = maxWidth * fade;
      ctx.stroke();
    }

    ctx.globalCompositeOperation = 'source-over';
  }
}
