import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';

//Agrandit en grand les images qui ont la classe .js-zoom
export default class Lightbox {
  constructor(element) {
    this.element = element;
    this.init();
  }

  init() {
    this.element.classList.add('lightbox');
    this.element.innerHTML = `<img class="lightbox__image" alt="" /><p class="lightbox__caption"></p>`;
    this.image = this.element.querySelector('.lightbox__image');
    this.caption = this.element.querySelector('.lightbox__caption');

    //Ouvre au clic sur une image .js-zoom
    document.addEventListener('click', (e) => {
      const img = e.target.closest('.js-zoom');
      if (img) this.open(img);
    });

    //Ferme au clic n'importe où dans la lightbox ou avec Échap
    this.element.addEventListener('click', this.close.bind(this));
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.close();
    });
  }

  open(img) {
    this.isOpen = true;
    this.image.src = img.src;
    this.caption.textContent = img.alt;
    ScrollSmoother.get()?.paused(true);

    gsap.set(this.element, { visibility: 'visible' });
    gsap.to(this.element, { opacity: 1, duration: 0.3 });
    gsap.fromTo(this.image, { scale: 0.85 }, { scale: 1, duration: 0.5, ease: 'expo.out' });
  }

  close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    ScrollSmoother.get()?.paused(false);
    gsap.to(this.element, { opacity: 0, duration: 0.3, onComplete: () => gsap.set(this.element, { visibility: 'hidden' }) });
  }
}
