import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';

//Fenêtre qui s'ouvre avec les liens href="#id-de-la-modale" (ex. #ia)
export default class Modal {
  constructor(element) {
    this.element = element;
    this.init();
  }

  init() {
    //Sort la modale du #smooth-content, sinon le position: fixed ne marche pas
    document.body.appendChild(this.element);

    //Ouvre au clic sur un lien #ia, ferme au clic sur un .js-modal-close
    document.addEventListener('click', (e) => {
      if (e.target.closest(`a[href="#${this.element.id}"]`)) {
        e.preventDefault();
        this.open();
      } else if (e.target.closest('.js-modal-close')) {
        this.close();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.close();
    });

    //Ouvre directement si l'adresse finit par #ia (ex. lien depuis une autre page)
    if (window.location.hash === `#${this.element.id}`) {
      window.addEventListener('loader:complete', () => this.open());
    }
  }

  open() {
    this.isOpen = true;
    ScrollSmoother.get()?.paused(true);

    gsap.set(this.element, { visibility: 'visible' });
    gsap.to(this.element, { opacity: 1, duration: 0.3 });
    gsap.fromTo(this.element.querySelector('.modal__box'), { y: 60 }, { y: 0, duration: 0.6, ease: 'expo.out' });
  }

  close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    ScrollSmoother.get()?.paused(false);
    gsap.to(this.element, { opacity: 0, duration: 0.3, onComplete: () => gsap.set(this.element, { visibility: 'hidden' }) });
  }
}
