import { gsap } from 'gsap';

export default class cursor {
  constructor(element) {
    this.element = element;
    this.options = {
      ease: 0.3, //Vitesse à laquelle la goutte suit la souris (0 à 1)
      textEase: 0.5, //Plus rapide sur le texte pour bien se placer
      sparks: 6, //Nombre de petites gouttes projetées au clic
    };

    //Position de la souris et de la goutte
    this.mouse = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    this.pos = { x: this.mouse.x, y: this.mouse.y };

    //Étirement de la goutte
    this.angle = 0;
    this.amount = 0;

    this.state = 'default';
    this.isDown = false;
    this.isVisible = false;

    this.init();
  }

  /* ==========================================================================
      / Init
     ========================================================================== */

  init() {
    //Pas de curseur personnalisé sur mobile et tablette (pas de souris)
    if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
      this.element.remove();
      return;
    }

    this.setOptions();
    this.createElements();
    this.initEvents();

    //Cache le curseur normal (voir _cursor.scss)
    document.documentElement.classList.add('has-cursor');

    this.update = this.update.bind(this);
    gsap.ticker.add(this.update);
  }

  /* ==========================================================================
      / Set Options (via les data-attributes du HTML)
     ========================================================================== */

  setOptions() {
    for (const key in this.options) {
      if (key in this.element.dataset) {
        this.options[key] = parseFloat(this.element.dataset[key]);
      }
    }
  }

  /* ==========================================================================
      / Création des éléments
     ========================================================================== */

  createElements() {
    this.element.setAttribute('aria-hidden', 'true');
    this.element.dataset.state = 'default';
    this.element.dataset.down = 'false';

    this.element.innerHTML = `
      <div class="cursor__drop">
        <div class="cursor__stretch">
          <div class="cursor__shape">
            <span class="cursor__arrow cursor__arrow--left">&larr;</span>
            <span class="cursor__label"></span>
            <span class="cursor__arrow cursor__arrow--right">&rarr;</span>
          </div>
        </div>
      </div>
      <div class="cursor__fx"></div>
    `;

    this.drop = this.element.querySelector('.cursor__drop');
    this.stretch = this.element.querySelector('.cursor__stretch');
    this.fx = this.element.querySelector('.cursor__fx');

    //quickSetter = la façon la plus rapide de déplacer un élément avec GSAP
    this.setX = gsap.quickSetter(this.drop, 'x', 'px');
    this.setY = gsap.quickSetter(this.drop, 'y', 'px');

    //Caché jusqu'au premier mouvement de la souris
    gsap.set(this.element, { autoAlpha: 0 });
  }

  /* ==========================================================================
      / Events
     ========================================================================== */

  initEvents() {
    this.onPointerMove = this.onPointerMove.bind(this);
    this.onPointerOver = this.onPointerOver.bind(this);
    this.onPointerDown = this.onPointerDown.bind(this);
    this.onPointerUp = this.onPointerUp.bind(this);
    this.onLeave = this.onLeave.bind(this);
    this.onScroll = this.onScroll.bind(this);

    document.addEventListener('pointermove', this.onPointerMove, {
      passive: true,
    });
    document.addEventListener('pointerover', this.onPointerOver);
    document.addEventListener('pointerdown', this.onPointerDown);
    document.addEventListener('pointerup', this.onPointerUp);
    document.addEventListener('pointercancel', this.onPointerUp);
    document.documentElement.addEventListener('mouseleave', this.onLeave);

    //Avec le ScrollSmoother, le contenu bouge sous la souris : on revérifie l'état
    window.addEventListener('scroll', this.onScroll, { passive: true });
  }

  onPointerMove(e) {
    this.mouse.x = e.clientX;
    this.mouse.y = e.clientY;

    //Premier mouvement (ou retour dans la page) : la goutte apparaît sous la souris
    if (!this.isVisible) {
      this.isVisible = true;
      this.pos.x = this.mouse.x;
      this.pos.y = this.mouse.y;
      gsap.to(this.element, { autoAlpha: 1, duration: 0.3 });
    }
  }

  onPointerOver(e) {
    //Pendant un drag, on garde l'état "glisser" même si la souris sort de la galerie
    if (this.isDown && this.state === 'drag') return;
    this.setState(this.getState(e.target));
  }

  onPointerDown(e) {
    this.isDown = true;
    this.element.dataset.down = 'true';

    if (this.state !== 'hide' && this.state !== 'drag') {
      this.splash(e.clientX, e.clientY);
    }
  }

  onPointerUp() {
    this.isDown = false;
    this.element.dataset.down = 'false';

    //Après un drag, la souris peut être ailleurs : on revérifie ce qu'il y a dessous
    this.onScroll();
  }

  onLeave() {
    this.isVisible = false;
    gsap.to(this.element, { autoAlpha: 0, duration: 0.3 });
  }

  onScroll() {
    if (!this.isVisible) return;
    const target = document.elementFromPoint(this.mouse.x, this.mouse.y);
    this.setState(this.getState(target));
  }

  /* ==========================================================================
      / États
     ========================================================================== */

  //Choisit l'état du curseur selon l'élément sous la souris
  getState(target) {
    if (!target || !target.closest) return 'default';

    //1. Choix forcé dans le HTML : data-cursor="view", "drag", "play", "hide"...
    const forced = target.closest('[data-cursor]');
    if (forced) return forced.dataset.cursor;

    //2. Champs et vidéo YouTube : on laisse le curseur normal
    if (target.closest('iframe, input, textarea, select')) return 'hide';

    //3. Liens et boutons
    const link = target.closest('a, button');
    if (link) {
      if (link.hasAttribute('download')) return 'download';
      if (link.target === '_blank') return 'external';
      return 'hover';
    }

    //4. Texte
    if (target.closest('h1, h2, h3, h4, p, li')) return 'text';

    return 'default';
  }

  setState(state) {
    if (state === this.state) return;
    this.state = state;
    this.element.dataset.state = state;
  }

  /* ==========================================================================
      / Effet au clic : ondes + éclaboussure
     ========================================================================== */

  splash(x, y) {
    //Deux ondes, comme une goutte qui touche l'eau
    for (let i = 0; i < 2; i++) {
      const ripple = document.createElement('div');
      ripple.className =
        i === 0 ? 'cursor__ripple' : 'cursor__ripple cursor__ripple--late';
      this.fx.appendChild(ripple);

      gsap.fromTo(
        ripple,
        {
          x: x,
          y: y,
          xPercent: -50,
          yPercent: -50,
          width: 10,
          height: 10,
          opacity: 1,
        },
        {
          width: 86,
          height: 86,
          opacity: 0,
          duration: 0.7,
          delay: i * 0.12,
          ease: 'power3.out',
          onComplete: () => ripple.remove(),
        },
      );
    }

    //Petites gouttes projetées autour
    for (let i = 0; i < this.options.sparks; i++) {
      const angle =
        (i / this.options.sparks) * Math.PI * 2 + Math.random() * 0.6;
      const distance = 22 + Math.random() * 18;

      const spark = document.createElement('div');
      spark.className = 'cursor__spark';
      this.fx.appendChild(spark);

      gsap.fromTo(
        spark,
        { x: x, y: y, xPercent: -50, yPercent: -50, scale: 1, opacity: 1 },
        {
          x: x + Math.cos(angle) * distance,
          y: y + Math.sin(angle) * distance + 8, //Retombe un peu, comme une vraie goutte
          scale: 0.3,
          opacity: 0,
          duration: 0.6,
          ease: 'power3.out',
          onComplete: () => spark.remove(),
        },
      );
    }
  }

  /* ==========================================================================
      / Boucle d'animation
     ========================================================================== */

  update() {
    //Rend le mouvement identique peu importe les FPS de l'écran
    const ratio = gsap.ticker.deltaRatio();
    const ease =
      this.state === 'text' ? this.options.textEase : this.options.ease;
    const follow = 1 - Math.pow(1 - ease, ratio);

    const prevX = this.pos.x;
    const prevY = this.pos.y;
    this.pos.x += (this.mouse.x - this.pos.x) * follow;
    this.pos.y += (this.mouse.y - this.pos.y) * follow;

    this.setX(this.pos.x);
    this.setY(this.pos.y);

    //Vitesse de la goutte
    const vx = (this.pos.x - prevX) / ratio;
    const vy = (this.pos.y - prevY) / ratio;
    const speed = Math.sqrt(vx * vx + vy * vy);

    //Étirement selon l'état
    let target = 0;
    if (this.state === 'default') {
      target = Math.min(speed / 20, 1);
    } else if (this.state === 'hover') {
      target = Math.min(speed / 20, 1) * 0.5;
    } else if (this.state === 'drag') {
      target = Math.min(Math.abs(vx) / 18, 1) * 0.5;
    }

    //Direction de l'étirement (seulement à l'horizontale pour glisser)
    if (this.state === 'drag') {
      this.angle = 0;
    } else if (speed > 0.6) {
      this.angle = (Math.atan2(vy, vx) * 180) / Math.PI;
    }

    this.amount += (target - this.amount) * (1 - Math.pow(0.75, ratio));

    const scaleX = 1 + this.amount * 0.9;
    const scaleY = 1 - this.amount * 0.35;

    //rotate > scale > rotate inverse : étire dans la direction du mouvement
    //sans faire tourner le contenu (les textes "Voir", "Glisser" restent droits)
    this.stretch.style.transform = `rotate(${this.angle}deg) scale(${scaleX}, ${scaleY}) rotate(${-this.angle}deg)`;
  }

  /* ==========================================================================
      / Destroy
     ========================================================================== */

  destroy() {
    gsap.ticker.remove(this.update);
    document.removeEventListener('pointermove', this.onPointerMove);
    document.removeEventListener('pointerover', this.onPointerOver);
    document.removeEventListener('pointerdown', this.onPointerDown);
    document.removeEventListener('pointerup', this.onPointerUp);
    document.removeEventListener('pointercancel', this.onPointerUp);
    document.documentElement.removeEventListener('mouseleave', this.onLeave);
    window.removeEventListener('scroll', this.onScroll);
    document.documentElement.classList.remove('has-cursor');
    this.element.innerHTML = '';
  }
}
